"""Email verification routes (generated by Shikshya, PX.303), under /api/auth/verify/: the link's token,
once, confirms the address; a signed-in user asks for a new link, at most one a minute, and always gets the same
answer; the status tells the banner whether to show."""
from rest_framework import status
from rest_framework.permissions import AllowAny, IsAuthenticated
from rest_framework.response import Response
from rest_framework.throttling import ScopedRateThrottle
from rest_framework.views import APIView

from . import core

BAD_LINK = {"detail": "This link is invalid, used or expired. Sign in and ask for a new one."}
SENT = {"detail": "If your email still needs confirming, a new link is on its way."}


class ConfirmView(APIView):
    """POST /api/auth/verify/confirm/ {"token"}: the token from the mailed link."""
    authentication_classes = []
    permission_classes = [AllowAny]
    throttle_classes = [ScopedRateThrottle]
    throttle_scope = "auth"

    def post(self, request):
        token = request.data.get("token", "") if hasattr(request.data, "get") else ""
        if core.confirm(token) is None:
            return Response(BAD_LINK, status=status.HTTP_400_BAD_REQUEST)
        return Response({"detail": "Your email is confirmed."})


class ResendView(APIView):
    """POST /api/auth/verify/resend/: a new link for the signed-in user; the same answer whatever happened."""
    permission_classes = [IsAuthenticated]
    throttle_classes = [ScopedRateThrottle]
    throttle_scope = "auth"

    def post(self, request):
        core.resend(request.user)
        return Response(SENT)


class StatusView(APIView):
    """GET /api/auth/verify/status/: whether verification is on and the signed-in user's email is confirmed."""
    permission_classes = [IsAuthenticated]

    def get(self, request):
        return Response({"on": core.on(), "verified": not core.needs(request.user)})
